const config = {
  "previewFeatures": [],
  "clientVersion": "7.5.0",
  "engineVersion": "280c870be64f457428992c43c1f6d557fab6e29e",
  "activeProvider": "postgresql",
  "inlineSchema": "// HarvestHub Database Schema\n// Matches lib/types.ts and lib/constants/index.ts\n\ngenerator client {\n  provider   = \"prisma-client-js\"\n  output     = \"../prisma/generated/client\"\n  engineType = \"binary\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n}\n\n// ============================================================================\n// ENUMS\n// ============================================================================\n\nenum UserRole {\n  ADMIN\n  VENDOR\n  BUYER\n}\n\nenum UserStatus {\n  ACTIVE\n  INACTIVE\n  BANNED\n}\n\nenum Gender {\n  MALE\n  FEMALE\n  OTHER\n}\n\nenum VendorStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  SUSPENDED\n}\n\nenum VendorCategory {\n  ELECTRONICS\n  COMPUTERS_OFFICE\n  HOME_APPLIANCES\n  FURNITURE\n  HOME_DECOR\n  KITCHEN_DINING\n  FASHION\n  BEAUTY\n  BABY_KIDS\n  TOYS_GAMES\n  AUTOMOTIVE\n  MOTORCYCLES\n  SPARE_PARTS\n  INDUSTRIAL\n  AGRICULTURE\n  SECURITY\n  GROCERY_FOOD\n  SERVICES\n  OTHERS\n}\n\nenum ProductCategory {\n  // Electronics\n  MOBILE_DEVICES\n  MOBILE_ACCESSORIES\n  AUDIO_WEARABLES\n  TV_VIDEO\n  CAMERAS\n  STORAGE_DEVICES\n  NETWORKING\n  COMPUTER_ACCESSORIES\n  // Computers & Office\n  COMPUTERS\n  DISPLAYS\n  PRINTING_SCANNING\n  OFFICE_EQUIPMENT\n  // Home Appliances\n  LARGE_APPLIANCES\n  KITCHEN_APPLIANCES\n  CLEANING_APPLIANCES\n  COOLING\n  // Furniture\n  LIVING_ROOM\n  BEDROOM\n  DINING\n  OFFICE_FURNITURE\n  STORAGE\n  OUTDOOR_FURNITURE\n  KIDS_FURNITURE\n  // Home Decor\n  HOME_DECOR\n  // Kitchen & Dining\n  COOKWARE\n  DINING_SETS\n  KITCHEN_TOOLS\n  KITCHEN_STORAGE\n  BEVERAGE\n  // Fashion\n  MENS_FASHION\n  WOMENS_FASHION\n  // Beauty & Personal Care\n  BEAUTY_PRODUCTS\n  PERSONAL_CARE\n  HAIR_WIGS\n  // Baby & Kids\n  BABY_ESSENTIALS\n  // Toys & Games\n  TOYS\n  // Automotive\n  CAR_ESSENTIALS\n  CAR_ELECTRONICS\n  CAR_MAINTENANCE\n  // Motorcycles\n  MOTORCYCLE_PARTS\n  // Spare Parts\n  SPARE_PARTS\n  // Industrial & Construction\n  INDUSTRIAL_EQUIPMENT\n  CONSTRUCTION_TOOLS\n  SAFETY_EQUIPMENT\n  // Agriculture\n  AGRICULTURE\n  // Security & Surveillance\n  SECURITY_SURVEILLANCE\n  // Grocery & Food\n  GROCERY\n  // Services & Others\n  SERVICES\n  OTHERS\n}\n\nenum Campus {\n  LONDON\n  BIRMINGHAM\n  GLASGOW\n  MANCHESTER\n  HOUSTON\n  NORTH_LONDON\n  KENT\n  TORONTO\n  GBAGADA\n  MAGODO\n  IKORODU\n  IBADAN_JERICHO\n  AKOBO\n  APAPA\n  SURULERE\n  ABEOKUTA\n  ILUPEJU\n  YABA\n  PORT_HARCOURT\n  OLUYOLE\n  OGBA\n  ANTHONY\n  ALIMOSHO\n  IKEJA\n  IKOYI\n  ISOLO\n  IYANA_IPAJA\n  ABULE_EGBA\n  GHANA\n  ABUJA\n  LEKKI\n  GLOBE\n  AJAH\n  ONLINE\n}\n\nenum Position {\n  HOD\n  ASST_HOD\n  SUB_TEAM_LEADER\n  TEAM_LEAD\n  SMALL_GROUP_LEADER\n  ASST_SMALL_GROUP_LEADER\n  ZONAL_COORDINATOR\n  COMMUNITY_LEADER\n  DISTRICT_PASTOR\n}\n\nenum OrderStatus {\n  PENDING\n  CONFIRMED\n  PROCESSING\n  READY_FOR_PICKUP\n  OUT_FOR_DELIVERY\n  DELIVERED\n  CANCELLED\n  REFUNDED\n}\n\nenum PaymentStatus {\n  PENDING\n  PAID\n  FAILED\n  REFUNDED\n}\n\nenum PaymentMethod {\n  WALLET\n  BANK_TRANSFER\n  BANK_TRANSFER_PROOF\n  CARD\n  USSD\n}\n\nenum DeliveryMethod {\n  PICKUP\n  DELIVERY\n}\n\nenum PickupService {\n  SUNDAY_FIRST\n  SUNDAY_SECOND\n  MIDWEEK\n  SPECIAL_EVENT\n}\n\nenum TransactionType {\n  DEPOSIT\n  WITHDRAWAL\n  PAYMENT\n  REFUND\n  COMMISSION\n  PAYOUT\n}\n\nenum TransactionStatus {\n  PENDING\n  COMPLETED\n  FAILED\n  REVERSED\n}\n\nenum BannerPosition {\n  TOP\n  HERO\n  SIDEBAR\n}\n\nenum BannerTheme {\n  BUSINESS\n  CHURCH\n  EVENT\n  PROMOTION\n}\n\nenum ReviewStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nenum AvailabilityRequestStatus {\n  PENDING\n  CONFIRMED\n  DECLINED\n  EXPIRED\n}\n\nenum AdStatus {\n  PENDING_PAYMENT\n  PENDING_APPROVAL\n  APPROVED\n  ACTIVE\n  EXPIRED\n  REJECTED\n}\n\nenum AdPaymentStatus {\n  PENDING\n  VERIFIED\n  REJECTED\n}\n\nenum ProofOfTransferStatus {\n  PENDING\n  VERIFIED\n  REJECTED\n}\n\nenum VoucherType {\n  PERCENTAGE\n  FIXED_AMOUNT\n  FREE_DELIVERY\n}\n\nenum MilestoneType {\n  FIRST_1000_VENDORS\n  FIRST_1000_BUYERS\n  FIRST_PURCHASE\n  FIRST_SALE\n  FIRST_REVIEW\n  VENDOR_100_SALES\n  CUSTOM\n}\n\nenum NotificationType {\n  ORDER_CONFIRMED\n  ORDER_READY\n  ORDER_DELIVERED\n  ORDER_CANCELLED\n  PAYMENT_SUCCESS\n  PAYMENT_FAILED\n  DELIVERY_UPDATE\n  VENDOR_MESSAGE\n  LOW_STOCK\n  NEW_PRODUCT\n  PROMOTION\n}\n\nenum ListingType {\n  PRODUCT\n  SERVICE\n}\n\nenum ServiceCategory {\n  GROOMING\n  BEAUTY_WELLNESS\n  CREATIVE\n  DIGITAL\n  WRITING_TRANSLATION\n  TUTORING_COACHING\n  HOME_SERVICES\n  FOOD_CATERING\n  EVENTS\n  FASHION_TAILORING\n  FITNESS\n  CONSULTING\n  OTHER_SERVICE\n}\n\nenum ServiceRateType {\n  FIXED\n  HOURLY\n  PER_SESSION\n  STARTING_FROM\n  CUSTOM\n}\n\nenum ServiceLocation {\n  ON_SITE\n  REMOTE\n  BOTH\n}\n\nenum BookingStatus {\n  PENDING\n  CONFIRMED\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n  NO_SHOW\n}\n\nenum VendorContentType {\n  IMAGE\n  VIDEO\n  TEXT\n  PROMO_BANNER\n}\n\nenum VendorContentStatus {\n  PENDING\n  APPROVED\n  REJECTED\n  ACTIVE\n  EXPIRED\n}\n\n// ============================================================================\n// MODELS\n// ============================================================================\n\nmodel User {\n  id             String     @id @default(cuid())\n  email          String     @unique\n  password       String\n  firstName      String\n  lastName       String\n  phoneNumber    String\n  role           UserRole   @default(BUYER)\n  profilePicture String?\n  emailVerified  Boolean    @default(false)\n  isActive       Boolean    @default(true)\n  status         UserStatus @default(ACTIVE)\n\n  // Password reset\n  resetToken       String?   @unique\n  resetTokenExpiry DateTime?\n\n  // Email verification\n  emailVerificationToken  String?   @unique\n  emailVerificationExpiry DateTime?\n\n  // Tracks user registration order for milestone features (e.g., first 1000 vendors/buyers)\n  registrationSequence Int? @unique\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  buyer                  Buyer?\n  vendor                 Vendor?\n  addresses              Address[]\n  notifications          Notification[]\n  wallet                 Wallet?\n  bannersCreated         Banner[]\n  pushSubscriptions      PushSubscription[]\n  notificationPreference NotificationPreference?\n  milestones             UserMilestone[]\n  advertisements         Advertisement[]\n  proofOfTransfers       ProofOfTransfer[]\n  voucherRedemptions     VoucherRedemption[]\n\n  @@index([email])\n  @@index([role])\n  @@index([status])\n  @@map(\"users\")\n}\n\nmodel Buyer {\n  id          String    @id @default(cuid())\n  userId      String    @unique\n  dateOfBirth DateTime?\n  gender      Gender?\n\n  // Preferences stored as JSON\n  preferences Json? @default(\"{}\")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user                 User                         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  cart                 Cart?\n  orders               Order[]\n  reviews              Review[]\n  availabilityRequests ProductAvailabilityRequest[]\n  bookings             Booking[]\n\n  @@index([userId])\n  @@map(\"buyers\")\n}\n\nmodel Vendor {\n  id                 String         @id @default(cuid())\n  userId             String         @unique\n  storeName          String\n  storeDescription   String?\n  category           VendorCategory\n  whatsappNumber     String\n  campus             Campus\n  position           Position?\n  status             VendorStatus   @default(PENDING)\n  isChurchAffiliated Boolean        @default(false)\n  commissionRate     Float          @default(0.05)\n  storeLogo          String?\n  storeBanner        String?\n\n  // Structured JSON fields\n  businessVerification Json?\n  storeSettings        Json  @default(\"{\\\"allowsPickup\\\":true,\\\"allowsDelivery\\\":false,\\\"pickupServices\\\":[],\\\"deliveryZones\\\":[]}\")\n\n  // Denormalized analytics\n  totalSales     Float @default(0)\n  totalOrders    Int   @default(0)\n  totalProducts  Int   @default(0)\n  averageRating  Float @default(0)\n  totalReviews   Int   @default(0)\n  conversionRate Float @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user                 User                         @relation(fields: [userId], references: [id], onDelete: Cascade)\n  products             Product[]\n  orders               Order[]\n  availabilityRequests ProductAvailabilityRequest[]\n  bookings             Booking[]\n  vendorContent        VendorContent[]\n\n  @@index([userId])\n  @@index([campus])\n  @@index([category])\n  @@index([status])\n  @@map(\"vendors\")\n}\n\nmodel Product {\n  id             String          @id @default(cuid())\n  vendorId       String\n  name           String\n  description    String\n  category       ProductCategory\n  price          Float\n  compareAtPrice Float?\n  discount       Float           @default(0)\n  stock          Int             @default(0)\n  images         String[]\n  mainImage      String\n  variants       Json?\n  tags           String[]        @default([])\n  isActive       Boolean         @default(true)\n  isFeatured     Boolean         @default(false)\n  views          Int             @default(0)\n  sales          Int             @default(0)\n  averageRating  Float           @default(0)\n  totalReviews   Int             @default(0)\n\n  // Service vendor support\n  listingType    ListingType @default(PRODUCT)\n  serviceDetails Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  vendor     Vendor      @relation(fields: [vendorId], references: [id], onDelete: Cascade)\n  reviews    Review[]\n  orderItems OrderItem[]\n  cartItems  CartItem[]\n  bookings   Booking[]\n\n  @@index([vendorId])\n  @@index([category])\n  @@index([isActive, isFeatured])\n  @@index([name])\n  @@index([price])\n  @@index([listingType])\n  @@map(\"products\")\n}\n\nmodel Cart {\n  id       String @id @default(cuid())\n  buyerId  String @unique\n  subtotal Float  @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  buyer Buyer      @relation(fields: [buyerId], references: [id], onDelete: Cascade)\n  items CartItem[]\n\n  @@index([buyerId])\n  @@map(\"carts\")\n}\n\nmodel CartItem {\n  id               String @id @default(cuid())\n  cartId           String\n  productId        String\n  quantity         Int    @default(1)\n  selectedVariants Json?\n  price            Float\n  subtotal         Float\n\n  addedAt DateTime @default(now())\n\n  // Relations\n  cart    Cart    @relation(fields: [cartId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n\n  @@unique([cartId, productId])\n  @@index([cartId])\n  @@index([productId])\n  @@map(\"cart_items\")\n}\n\nmodel Order {\n  id              String         @id @default(cuid())\n  orderNumber     String         @unique\n  buyerId         String\n  vendorId        String\n  status          OrderStatus    @default(PENDING)\n  subtotal        Float\n  deliveryFee     Float          @default(0)\n  total           Float\n  paymentStatus   PaymentStatus  @default(PENDING)\n  paymentMethod   PaymentMethod\n  deliveryMethod  DeliveryMethod\n  deliveryAddress Json?\n  pickupDetails   Json?\n  notes           String?\n  statusHistory   Json           @default(\"[]\")\n\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n  completedAt DateTime?\n\n  // Relations\n  buyer            Buyer             @relation(fields: [buyerId], references: [id])\n  vendor           Vendor            @relation(fields: [vendorId], references: [id])\n  items            OrderItem[]\n  transactions     Transaction[]\n  proofOfTransfers ProofOfTransfer[]\n\n  @@index([buyerId])\n  @@index([vendorId])\n  @@index([status])\n  @@index([orderNumber])\n  @@index([createdAt])\n  @@map(\"orders\")\n}\n\nmodel OrderItem {\n  id               String @id @default(cuid())\n  orderId          String\n  productId        String\n  productName      String\n  productImage     String\n  quantity         Int\n  selectedVariants Json?\n  price            Float\n  subtotal         Float\n\n  // Relations\n  order   Order   @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  product Product @relation(fields: [productId], references: [id])\n\n  @@index([orderId])\n  @@index([productId])\n  @@map(\"order_items\")\n}\n\nmodel Address {\n  id           String  @id @default(cuid())\n  userId       String\n  label        String\n  fullName     String\n  phoneNumber  String\n  addressLine1 String\n  addressLine2 String?\n  city         String\n  state        String\n  campus       Campus?\n  landmark     String?\n  isDefault    Boolean @default(false)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"addresses\")\n}\n\nmodel Wallet {\n  id       String  @id @default(cuid())\n  userId   String  @unique\n  balance  Float   @default(0)\n  currency String  @default(\"NGN\")\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  transactions Transaction[]\n\n  @@index([userId])\n  @@map(\"wallets\")\n}\n\nmodel Transaction {\n  id            String            @id @default(cuid())\n  walletId      String\n  type          TransactionType\n  amount        Float\n  balanceBefore Float\n  balanceAfter  Float\n  status        TransactionStatus @default(PENDING)\n  reference     String            @unique\n  description   String\n  metadata      Json?\n  orderId       String?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  wallet Wallet @relation(fields: [walletId], references: [id], onDelete: Cascade)\n  order  Order? @relation(fields: [orderId], references: [id])\n\n  @@index([walletId])\n  @@index([reference])\n  @@index([type])\n  @@index([status])\n  @@index([createdAt])\n  @@map(\"transactions\")\n}\n\nmodel Review {\n  id                 String       @id @default(cuid())\n  productId          String\n  buyerId            String\n  orderId            String\n  rating             Int\n  comment            String?\n  images             String[]     @default([])\n  isVerifiedPurchase Boolean      @default(true)\n  helpfulCount       Int          @default(0)\n  notHelpfulCount    Int          @default(0)\n  isFlagged          Boolean      @default(false)\n  status             ReviewStatus @default(PENDING)\n  vendorResponse     String?\n  vendorRespondedAt  DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  product Product      @relation(fields: [productId], references: [id], onDelete: Cascade)\n  buyer   Buyer        @relation(fields: [buyerId], references: [id])\n  votes   ReviewVote[]\n\n  @@unique([productId, buyerId, orderId])\n  @@index([productId])\n  @@index([buyerId])\n  @@index([rating])\n  @@map(\"reviews\")\n}\n\nmodel Banner {\n  id              String         @id @default(cuid())\n  title           String\n  subtitle        String?\n  description     String?\n  imageUrl        String\n  linkUrl         String?\n  actions         Json?\n  position        BannerPosition @default(HERO)\n  theme           BannerTheme    @default(BUSINESS)\n  accentColor     String?\n  details         String?\n  knowMoreLabel   String?\n  isActive        Boolean        @default(true)\n  startDate       DateTime       @default(now())\n  endDate         DateTime?\n  displayOrder    Int            @default(0)\n  targetAudience  UserRole[]     @default([])\n  clickCount      Int            @default(0)\n  impressionCount Int            @default(0)\n  createdBy       String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  creator User @relation(fields: [createdBy], references: [id])\n\n  @@index([isActive, startDate, endDate])\n  @@index([position])\n  @@map(\"banners\")\n}\n\n// ── Commission Configuration (per-category defaults, admin-managed) ──\nmodel CommissionConfig {\n  id        String         @id @default(cuid())\n  category  VendorCategory @unique\n  rate      Float\n  createdAt DateTime       @default(now())\n  updatedAt DateTime       @updatedAt\n\n  @@map(\"commission_configs\")\n}\n\nmodel Notification {\n  id       String           @id @default(cuid())\n  userId   String\n  type     NotificationType\n  title    String\n  message  String\n  link     String?\n  isRead   Boolean          @default(false)\n  metadata Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, isRead])\n  @@index([createdAt])\n  @@map(\"notifications\")\n}\n\n// ============================================================================\n// NEW MODELS\n// ============================================================================\n\nmodel PushSubscription {\n  id       String @id @default(cuid())\n  userId   String\n  endpoint String\n  keys     Json\n\n  createdAt DateTime @default(now())\n\n  // Relations\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"push_subscriptions\")\n}\n\nmodel NotificationPreference {\n  id                 String  @id @default(cuid())\n  userId             String  @unique\n  emailNotifications Boolean @default(true)\n  smsNotifications   Boolean @default(false)\n  pushNotifications  Boolean @default(true)\n  orderUpdates       Boolean @default(true)\n  promotions         Boolean @default(true)\n  vendorMessages     Boolean @default(true)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@map(\"notification_preferences\")\n}\n\nmodel ProductAvailabilityRequest {\n  id             String                    @id @default(cuid())\n  buyerId        String\n  vendorId       String\n  items          Json\n  status         AvailabilityRequestStatus @default(PENDING)\n  buyerNote      String?\n  vendorResponse String?\n  expiresAt      DateTime\n\n  createdAt   DateTime  @default(now())\n  respondedAt DateTime?\n\n  // Relations\n  buyer  Buyer  @relation(fields: [buyerId], references: [id])\n  vendor Vendor @relation(fields: [vendorId], references: [id])\n\n  @@index([buyerId])\n  @@index([vendorId])\n  @@index([status])\n  @@index([expiresAt])\n  @@map(\"product_availability_requests\")\n}\n\nmodel Advertisement {\n  id              String    @id @default(cuid())\n  advertiserId    String\n  title           String\n  subtitle        String?\n  ctaText         String?\n  ctaLink         String?\n  imageUrl        String\n  imagePublicId   String?\n  status          AdStatus  @default(PENDING_PAYMENT)\n  dailyRate       Float\n  startDate       DateTime?\n  endDate         DateTime?\n  totalPaid       Float     @default(0)\n  rejectionReason String?\n  impressions     Int       @default(0)\n  clicks          Int       @default(0)\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  advertiser User                @relation(fields: [advertiserId], references: [id])\n  payments   AdvertiserPayment[]\n\n  @@index([advertiserId])\n  @@index([status])\n  @@index([startDate, endDate])\n  @@map(\"advertisements\")\n}\n\nmodel AdvertiserPayment {\n  id                 String          @id @default(cuid())\n  advertisementId    String\n  amount             Float\n  proofOfTransferUrl String?\n  proofPublicId      String?\n  bankReference      String?\n  status             AdPaymentStatus @default(PENDING)\n  verifiedBy         String?\n  verifiedAt         DateTime?\n\n  createdAt DateTime @default(now())\n\n  // Relations\n  advertisement Advertisement @relation(fields: [advertisementId], references: [id], onDelete: Cascade)\n\n  @@index([advertisementId])\n  @@index([status])\n  @@map(\"advertiser_payments\")\n}\n\nmodel ProofOfTransfer {\n  id            String                @id @default(cuid())\n  orderId       String?\n  userId        String\n  imageUrl      String\n  imagePublicId String?\n  bankReference String?\n  amount        Float\n  status        ProofOfTransferStatus @default(PENDING)\n  verifiedBy    String?\n  verifiedAt    DateTime?\n  notes         String?\n\n  createdAt DateTime @default(now())\n\n  // Relations\n  user  User   @relation(fields: [userId], references: [id])\n  order Order? @relation(fields: [orderId], references: [id])\n\n  @@index([userId])\n  @@index([orderId])\n  @@index([status])\n  @@map(\"proof_of_transfers\")\n}\n\nmodel Voucher {\n  id                   String      @id @default(cuid())\n  code                 String      @unique\n  type                 VoucherType\n  value                Float\n  minOrderAmount       Float?      @default(0)\n  maxDiscount          Float?\n  usageLimit           Int?\n  usedCount            Int         @default(0)\n  perUserLimit         Int         @default(1)\n  validFrom            DateTime\n  validTo              DateTime\n  isActive             Boolean     @default(true)\n  applicableCategories Json?       @default(\"[]\")\n  applicableVendors    Json?       @default(\"[]\")\n  createdBy            String\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  redemptions VoucherRedemption[]\n\n  @@index([code])\n  @@index([isActive, validFrom, validTo])\n  @@map(\"vouchers\")\n}\n\nmodel VoucherRedemption {\n  id              String  @id @default(cuid())\n  voucherId       String\n  userId          String\n  orderId         String?\n  discountApplied Float\n\n  redeemedAt DateTime @default(now())\n\n  // Relations\n  voucher Voucher @relation(fields: [voucherId], references: [id])\n  user    User    @relation(fields: [userId], references: [id])\n\n  @@index([voucherId])\n  @@index([userId])\n  @@index([orderId])\n  @@map(\"voucher_redemptions\")\n}\n\nmodel UserMilestone {\n  id            String        @id @default(cuid())\n  userId        String\n  milestoneType MilestoneType\n  label         String\n  metadata      Json?\n\n  achievedAt DateTime @default(now())\n\n  // Relations\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId])\n  @@index([milestoneType])\n  @@map(\"user_milestones\")\n}\n\nmodel Booking {\n  id         String        @id @default(cuid())\n  productId  String\n  buyerId    String\n  vendorId   String\n  date       DateTime\n  startTime  String\n  endTime    String?\n  status     BookingStatus @default(PENDING)\n  notes      String?\n  totalPrice Float\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  product Product @relation(fields: [productId], references: [id], onDelete: Cascade)\n  buyer   Buyer   @relation(fields: [buyerId], references: [id])\n  vendor  Vendor  @relation(fields: [vendorId], references: [id])\n\n  @@index([productId])\n  @@index([buyerId])\n  @@index([vendorId])\n  @@index([date])\n  @@index([status])\n  @@map(\"bookings\")\n}\n\nmodel ReviewVote {\n  id       String  @id @default(cuid())\n  reviewId String\n  userId   String\n  helpful  Boolean\n\n  createdAt DateTime @default(now())\n\n  // Relations\n  review Review @relation(fields: [reviewId], references: [id], onDelete: Cascade)\n\n  @@unique([reviewId, userId])\n  @@index([reviewId])\n  @@map(\"review_votes\")\n}\n\nmodel BugReport {\n  id          String  @id @default(cuid())\n  userId      String?\n  title       String\n  description String\n  category    String\n  severity    String  @default(\"medium\")\n  status      String  @default(\"open\")\n  screenshot  String?\n  metadata    Json?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([status])\n  @@index([severity])\n  @@map(\"bug_reports\")\n}\n\nmodel VendorContent {\n  id              String              @id @default(cuid())\n  vendorId        String\n  type            VendorContentType\n  title           String\n  description     String?\n  mediaUrl        String?\n  mediaPublicId   String?\n  textContent     String?\n  status          VendorContentStatus @default(PENDING)\n  rejectionReason String?\n  usageRights     Boolean             @default(true)\n  targetPlatform  String?\n  validFrom       DateTime?\n  validTo         DateTime?\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  // Relations\n  vendor Vendor @relation(fields: [vendorId], references: [id], onDelete: Cascade)\n\n  @@index([vendorId])\n  @@index([status])\n  @@index([type])\n  @@map(\"vendor_content\")\n}\n"
}

